        passed: s2.tw0_ignition >= minU2 && s2.tw0_ignition <= maxU2,
        actualStr: `${s2.tw0_ignition.toFixed(2)}`,
        limitStr: `${minU2.toFixed(2)} - ${maxU2.toFixed(2)}`,
        detail: "Stage 2 ignition thrust-to-weight"
