        id: "stage3_tw",
        label: "Stage 3 T/W0",
        passed: s3.tw0_ignition >= minS3 && s3.tw0_ignition <= maxS3,
        actualStr: `${s3.tw0_ignition.toFixed(2)}`,
        limitStr: `${minS3.toFixed(2)} - ${maxS3.toFixed(2)}`,
        detail: "Stage 3 ignition thrust-to-weight"
