      passed: dvDel >= dvReq - 10,
      actualStr: formatValueWithUnit(dvDel, "velocity", unitSystem, 0),
      limitStr: `>= ${formatValueWithUnit(dvReq, "velocity", unitSystem, 0)}`,
      detail: "Delivered ideal impulse vs mission + margin requirement"
